css:
@import url("https://fonts.googleapis.com/css2?family=Tenor+Sans&family=Figtree:wght@400;600&display=swap");
:root{--bk:#101010;--bk2:#1B1B1B;--bn:#E9E4DA;--mu:#9A958C;--ln:#2A2A2A;--s:"Tenor Sans",system-ui,sans-serif;--b:"Figtree",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.65;color:#D8D3C9;background:var(--bk)}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--s);font-weight:400;margin:0;line-height:1.1;color:#fff;letter-spacing:.04em;text-transform:uppercase}
.wrap{max-width:1300px;margin:0 auto;padding:0 24px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--bn);color:#000;padding:8px;z-index:99}
:focus-visible{outline:2px solid var(--bn);outline-offset:3px}
.hd{position:fixed;top:0;left:0;right:0;z-index:40;background:linear-gradient(rgba(0,0,0,.6),transparent)}.nav{display:flex;justify-content:space-between;align-items:center;height:80px}
.logo{font-family:var(--s);font-size:22px;letter-spacing:.2em;text-decoration:none;color:#fff;text-transform:uppercase}
.menu{display:flex;gap:28px;list-style:none;margin:0;padding:0;font-size:14px;letter-spacing:.12em;text-transform:uppercase}.menu a{text-decoration:none}.menu a:hover{color:#fff}
.burger{display:none;background:none;border:1px solid #fff;color:#fff;padding:6px 10px;cursor:pointer}
.btn{display:inline-flex;align-items:center;padding:14px 28px;border:1px solid var(--bn);color:var(--bn);text-decoration:none;font-size:14px;letter-spacing:.14em;text-transform:uppercase;background:transparent;cursor:pointer;font-family:var(--b)}
.btn:hover{background:var(--bn);color:#000}.btn.f{background:var(--bn);color:#000}
.hero{height:100vh;min-height:620px;position:relative;display:flex;align-items:flex-end}.hero img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.hero::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 40%,rgba(0,0,0,.75))}
.hero .c{position:relative;z-index:1;padding-bottom:70px}.hero h1{font-size:clamp(42px,6.8vw,104px)}.hero p{font-size:19px;max-width:46ch;margin:16px 0 26px;color:#E6E1D8}
section{padding:90px 0}.sh{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:26px;flex-wrap:wrap}.sh h2{font-size:clamp(34px,4.4vw,56px)}
.chips{display:flex;gap:6px;flex-wrap:wrap}.chips button{background:none;border:1px solid var(--ln);color:var(--mu);padding:8px 16px;font:inherit;font-size:13px;letter-spacing:.12em;text-transform:uppercase;cursor:pointer}.chips button[aria-pressed=true]{border-color:var(--bn);color:#fff}
.gal{columns:3 320px;column-gap:12px}.gal button{display:block;width:100%;border:0;padding:0;margin:0 0 12px;background:none;cursor:zoom-in;break-inside:avoid;position:relative}
.gal img{width:100%;transition:opacity .3s}.gal button:hover img{opacity:.8}
.gal span{position:absolute;left:12px;bottom:10px;font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#fff;opacity:0;transition:.3s}.gal button:hover span,.gal button:focus span{opacity:1}
.about{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}.about img{width:100%;aspect-ratio:4/5;object-fit:cover}.about p{font-size:19px}
.awards{display:flex;gap:30px;flex-wrap:wrap;margin-top:26px;color:var(--mu);font-size:14px;letter-spacing:.08em;text-transform:uppercase}
.pk{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--ln);border:1px solid var(--ln)}.pk div{background:var(--bk);padding:32px;display:flex;flex-direction:column}
.pk h3{font-size:24px}.pk .am{font-family:var(--s);font-size:38px;color:#fff;margin:12px 0}.pk ul{padding-left:18px;margin:0 0 24px;color:var(--mu)}.pk .btn{margin-top:auto;align-self:flex-start}
.qt{text-align:center;max-width:860px;margin:0 auto}.qt p{font-family:var(--s);font-size:clamp(24px,3vw,38px);line-height:1.35;color:#fff;margin:0 0 16px}.qt cite{font-style:normal;color:var(--mu);letter-spacing:.1em;text-transform:uppercase;font-size:13px}
.bk{display:grid;grid-template-columns:1fr 1fr;gap:50px}.bk p{font-size:18px}
form{display:grid;gap:14px}label{font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:var(--mu)}
input,select,textarea{width:100%;background:var(--bk2);border:1px solid var(--ln);color:#fff;padding:12px 14px;font:inherit;margin-top:6px}
.lb{position:fixed;inset:0;background:rgba(0,0,0,.95);z-index:80;display:none;align-items:center;justify-content:center}.lb.on{display:flex}
.lb img{max-width:90vw;max-height:84vh;object-fit:contain}.lb button{position:absolute;background:none;border:0;color:#fff;font-size:40px;cursor:pointer;padding:10px 18px}
.lb .x{top:10px;right:10px}.lb .pv{left:10px;top:50%;transform:translateY(-50%)}.lb .nx{right:10px;top:50%;transform:translateY(-50%)}.lb p{position:absolute;bottom:20px;left:0;right:0;text-align:center;letter-spacing:.1em;text-transform:uppercase;font-size:13px}
footer{border-top:1px solid var(--ln);padding:30px 0;font-size:14px;color:var(--mu)}.ft{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}
@media(max-width:900px){.menu{display:none}.burger{display:block}.menu.open{display:flex;flex-direction:column;position:absolute;top:80px;left:0;right:0;background:var(--bk);padding:20px 24px;gap:14px}
.about,.bk{grid-template-columns:1fr}.pk{grid-template-columns:1fr}}

