const G=[["1470071459604-3b5ec3a7fe05","Landscape","Morning mist, Senja",900,600],["1483985988355-763728e1935b","Portrait","Winter coat, Oslo",700,1000],["1441974231531-c6227db76b6e","Landscape","Forest path, Lyngen",900,600],["1509631179647-0177331693ae","Portrait","Colour study, Bergen",700,1000],["1492691527719-9d1e07e534b4","Landscape","Above the clouds",900,600],["1445205170230-053b83016050","Street","Market rail, Copenhagen",900,700],["1451187580459-43490279c0fa","Landscape","Night lights from above",900,600],["1515886657613-9f3515b0c78f","Street","Yellow, Stockholm",700,900],["1506905925346-21bda4d32df4","Landscape","Peaks at sunrise",900,600]];
const $=id=>document.getElementById(id);let cur=[],idx=0;
function gal(c){cur=G.filter(g=>c==='all'||g[1]===c);$('gal').innerHTML=cur.map((g,i)=>`<button type="button" data-i="${i}" aria-label="Open photo: ${g[2]}"><img src="https://images.unsplash.com/photo-${g[0]}?w=700&q=75&auto=format&fit=crop" alt="${g[2]}" width="${g[3]}" height="${g[4]}" loading="lazy"><span>${g[2]}</span></button>`).join('')}
$('chips').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('chips').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));gal(b.dataset.c)};gal('all');
function show(i){idx=(i+cur.length)%cur.length;const g=cur[idx];$('li').src=`https://images.unsplash.com/photo-${g[0]}?w=1800&q=85&auto=format&fit=max`;$('li').alt=g[2];$('lc').textContent=g[2]+' · '+(idx+1)+' of '+cur.length}
$('gal').onclick=e=>{const b=e.target.closest('[data-i]');if(!b)return;show(+b.dataset.i);$('lb').classList.add('on');$('lx').focus()};
const close=()=>$('lb').classList.remove('on');$('lx').onclick=close;$('lp').onclick=()=>show(idx-1);$('ln').onclick=()=>show(idx+1);
document.addEventListener('keydown',e=>{if(!$('lb').classList.contains('on'))return;if(e.key==='Escape')close();if(e.key==='ArrowLeft')show(idx-1);if(e.key==='ArrowRight')show(idx+1)});
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
